    private fun bars() = closes.indices.map { Bar(it.toLong(), closes[it], highs[it], lows[it], closes[it], 1000.0) }

    private fun check(name: String, expected: DoubleArray, actual: DoubleArray) {
        for ((k, i) in idx.withIndex()) {
            val e = expected[k]
            val a = actual[i]
            if (e.isNaN()) assertTrue("$name[$i] should be NaN, was $a", a.isNaN())
            else assertEquals("$name[$i]", e, a, 1e-9)
        }
    }

    @Test fun emaMatchesPandas() = check("ema", expectedEma, Indicators.ema(closes, 12))
    @Test fun rsiMatchesPandas() = check("rsi", expectedRsi, Indicators.rsi(closes, 14))
    @Test fun atrMatchesPandas() = check("atr", expectedAtr, Indicators.atr(bars(), 14))

    @Test fun perfectlyFlatPriceGivesRsi50NotNaN() {
        val flat = DoubleArray(40) { 50.0 }
        assertEquals(50.0, Indicators.rsi(flat, 14).last(), 0.0)
    }

    @Test fun onlyGainsGivesRsi100() {
        val rising = DoubleArray(40) { 10.0 + it }
        assertEquals(100.0, Indicators.rsi(rising, 14).last(), 0.0)
    }
}
